    for a in range(tries):
        try:
            req = urllib.request.Request(url, headers=UA)
            r = urllib.request.urlopen(req, timeout=30).read()
            return r if binary else r.decode('utf-8','ignore')
        except Exception as e:
            if a == tries-1: raise
            time.sleep(1)

def player_response(vid):
    html = fetch(f"https://www.youtube.com/watch?v={vid}&bpctr=9999999999&has_verified=1")
    i = html.index('ytInitialPlayerResponse')
    brace = html.index('{', i)
    data, _ = json.JSONDecoder().raw_decode(html[brace:])
    return data

