       "F":"hT_nvWreIhg","G":"lp-EO5I60KA","H":"RBumgq5yVrA","I":"rYEDA3JcQqw","J":"lY2yjAdbvdQ"}

meta = {}
for k, vid in ids.items():
    try:
        d = player_response(vid)
        dur = int(d["videoDetails"]["lengthSeconds"])
