        meta[k] = dict(vid=vid, dur=dur, w=w, h=h, frames=frames, cols=cols, rows=rows, urlpat=urlpat, sigh=sigh)
        print(f"{k}: dur={dur}s frames={frames} grid={cols}x{rows} nimg={nimg}", flush=True)
        got = 0
        for im_ in range(nimg):
            url = urlpat.replace('$M', str(im_)) + f'&sigh={sigh}'
            try:
                data = fetch(url, binary=True)
                open(f"sb/{k}_{im_}.jpg","wb").write(data)
                got += 1
            except Exception as e:
                print(k, im_, "ERR", repr(e)[:80], flush=True)
        print(f"{k}: {got}/{nimg} grids saved", flush=True)
    except Exception as e:
        print(k, "META ERR", repr(e)[:120], flush=True)

json.dump(meta, open("sb/meta.json","w"))
